<article class="gamification-detail gamification-team-detail" style="--team-color:<?php echo utf8_htmlentities($team['color']) ?>"><?php if ($team['banner_path']): ?><div class="gamification-team-hero"><img src="<?php echo utf8_htmlentities(url($team['banner_path'])) ?>" alt="" /></div><?php endif ?><header><?php if ($team['logo_path']): ?><img class="gamification-team-logo" src="<?php echo utf8_htmlentities(url($team['logo_path'])) ?>" alt="" /><?php endif ?><h1><?php echo utf8_htmlentities($team['title']) ?></h1></header><div class="gamification-copy"><?php echo nl2br(utf8_htmlentities($team['description'])) ?></div><h2><?php echo $this->lang('Roster') ?></h2><ul class="gamification-roster"><?php foreach ($members as $member): ?><li><strong><?php echo utf8_htmlentities($member['display_name']) ?></strong><?php if ($member['role']): ?> <span><?php echo utf8_htmlentities($member['role']) ?></span><?php endif ?><?php if ($member['captain']): ?> <span class="gamification-badge"><?php echo $this->lang('Captain') ?></span><?php endif ?></li><?php endforeach ?></ul></article>
